// @ts-check
/**
 * @module make-holiday-table
 * Generates data/holiday-table.js, the built-in holiday table (HOL-013, NFR-003, DEC-024): the
 * national public holidays of the seven countries the holiday service does not cover, for the
 * years of `tableYears`, from the dev-only library `date-holidays`. It runs at development time
 * only; the page never imports the library. `domain/holiday-table.js` reads the generated file.
 * Run it with `node scripts/make-holiday-table.mjs`.
 */
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import Holidays from "date-holidays";

/** Country codes of the table (DEC-024). */
export const tableCountries = Object.freeze(["IN", "IL", "MY", "PK", "SA", "TW", "AE"]);

/** Years of the table (HOL-013). */
export const tableYears = Object.freeze([2026, 2027, 2028]);

/** The only holiday type kept (DEC-024). */
const keptType = "public";

const dayMs = 24 * 60 * 60 * 1000;

/**
 * @typedef {object} TableRow One day of a holiday in the table.
 * @property {string} date `YYYY-MM-DD`.
 * @property {string} name English name.
 */

/**
 * @typedef {object} LibraryHoliday The parts of a `date-holidays` holiday this script reads.
 * @property {string} date Local start, `YYYY-MM-DD hh:mm:ss` with an optional offset.
 * @property {Date} start
 * @property {Date} end
 * @property {string} name
 * @property {string} type
 * @property {string} rule
 */

/**
 * @param {string} date `YYYY-MM-DD`.
 * @param {number} days Days to add.
 * @returns {string} The calendar date `days` later, `YYYY-MM-DD`.
 */
function addDays(date, days) {
  return new Date(Date.parse(`${date}T00:00:00Z`) + days * dayMs).toISOString().slice(0, 10);
}

/**
 * Throws unless the library has an English name for the holiday's rule (NFR-003).
 * @param {Holidays} library The library, set to one country.
 * @param {LibraryHoliday} holiday
 * @param {string} code Country code, for the message.
 * @returns {void}
 */
function requireEnglishName(library, holiday, code) {
  // The rules with their names in every language are a property the library does not type.
  const { holidays: rules } = /** @type {{ holidays: Record<string, { name?: unknown }> }} */ (
    /** @type {unknown} */ (library)
  );
  const names = rules[holiday.rule]?.name;
  if (typeof names !== "object" || names === null || !("en" in names)) {
    throw new Error(
      `date-holidays has no English name for ${code} ${holiday.date} (${holiday.name})`,
    );
  }
}

/**
 * One row per day of a holiday: a holiday of several days (an Eid) gives a row for each day.
 * @param {LibraryHoliday} holiday
 * @returns {TableRow[]}
 */
function rowsOf(holiday) {
  const first = holiday.date.slice(0, 10);
  const days = Math.max(1, Math.round((holiday.end.getTime() - holiday.start.getTime()) / dayMs));
  return Array.from({ length: days }, (_, index) => ({
    date: addDays(first, index),
    name: holiday.name,
  }));
}

/**
 * The whole-country public holidays of one country for the table's years, sorted by date.
 * @param {string} code Country code of `tableCountries`.
 * @returns {TableRow[]}
 * @throws {Error} If a kept holiday has no English name.
 */
export function countryRows(code) {
  const library = new Holidays(code, { types: [keptType] });
  const holidays = tableYears.flatMap(
    (year) => /** @type {LibraryHoliday[]} */ (library.getHolidays(year, "en")),
  );
  const kept = holidays.filter((holiday) => holiday.type === keptType);
  kept.forEach((holiday) => requireEnglishName(library, holiday, code));
  return kept
    .flatMap(rowsOf)
    .filter((row) => tableYears.includes(Number(row.date.slice(0, 4))))
    .sort((a, b) => a.date.localeCompare(b.date));
}

/**
 * @param {TableRow[]} rows
 * @returns {string} The rows as source lines of a frozen list.
 */
function listSource(rows) {
  const lines = rows.map(
    (row) => `      { date: ${JSON.stringify(row.date)}, name: ${JSON.stringify(row.name)} },`,
  );
  return ["Object.freeze([", ...lines, "    ])"].join("\n");
}

/**
 * The text of data/holiday-table.js.
 * @param {Record<string, TableRow[]>} rowsByCountry
 * @param {string} libraryVersion Version of `date-holidays` that made the rows.
 * @returns {string}
 */
export function tableSource(rowsByCountry, libraryVersion) {
  const countries = Object.entries(rowsByCountry)
    .map(([code, rows]) => `    ${code}: ${listSource(rows)},`)
    .join("\n");
  return `// @ts-check
/**
 * @module data/holiday-table
 * The built-in holiday table (HOL-013, DEC-024): the national public holidays of ${tableCountries.join(", ")}
 * for ${tableYears[0]} to ${tableYears[tableYears.length - 1]}, one row per day off. It holds data only;
 * \`domain/holiday-table.js\` reads it.
 *
 * Generated by scripts/make-holiday-table.mjs from date-holidays ${libraryVersion}
 * (https://github.com/commenthol/date-holidays). Never edit it by hand; run the script again.
 * Data licence: CC BY-SA 3.0 (https://creativecommons.org/licenses/by-sa/3.0/), as the library's
 * README states for its holiday data; its LICENSE file names CC BY-SA 4.0. The library's code is ISC.
 * Islamic holidays are calculated and can differ by a day from the official announcement.
 */

/**
 * @typedef {object} TableHoliday One day of a holiday.
 * @property {string} date \`YYYY-MM-DD\`.
 * @property {string} name English name.
 */

/**
 * @type {Readonly<{ years: readonly number[], countries: Readonly<Record<string, readonly TableHoliday[]>> }>}
 */
export const holidayTable = Object.freeze({
  years: Object.freeze([${tableYears.join(", ")}]),
  countries: Object.freeze({
${countries}
  }),
});
`;
}

/** Writes data/holiday-table.js for the repository when this file is started from the command line. */
async function main() {
  const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
  const manifest = path.join(root, "node_modules", "date-holidays", "package.json");
  const { version } = JSON.parse(await readFile(manifest, "utf8"));
  const rowsByCountry = Object.fromEntries(tableCountries.map((code) => [code, countryRows(code)]));
  await writeFile(path.join(root, "data", "holiday-table.js"), tableSource(rowsByCountry, version));
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await main();
}
